class Solution {
    public List<Boolean> canEat(int[] candiesCount,int[][] queries){
        long[] prefix=new long[candiesCount.length+1];
        for(int i=0;i<candiesCount.length;i++)prefix[i+1]=prefix[i]+candiesCount[i];
        List<Boolean> answer=new ArrayList<>();
        for(int[] query:queries){
            long minimum=(long)query[1]+1,maximum=minimum*query[2];
            int type=query[0];
            answer.add(maximum>prefix[type]&&minimum<=prefix[type+1]);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun canEat(candiesCount:IntArray,queries:Array<IntArray>):List<Boolean>{
        val prefix=LongArray(candiesCount.size+1);
        for(i in candiesCount.indices)prefix[i+1]=prefix[i]+candiesCount[i];
        return queries.map{
            query->val minimum=query[1].toLong()+1;
            val maximum=minimum*query[2];
            val type=query[0];
            maximum>prefix[type]&&minimum<=prefix[type+1]
        }
    }
}

